func TestReproNilDeref(t *testing.T) {
	var recovered interface{}
	func() {
		defer func() { recovered = recover() }()
		var m *Metric
		_ = m.Labels["env"]
	}()
	if recovered == nil { t.Fatal("expected nil dereference panic") }
}
